"""ARENA u03 的 10 道测验（沿用旧版）"""
from unitlib import Q
QUIZ = [
  Q('下面哪个变换**不是**线性变换？', ['绕原点旋转 45°', '沿 x 轴拉伸 2 倍', '把所有点向右平移 1 个单位', '剪切：$(x, y) \\mapsto (x + y, y)$'], 2, '平移会移动原点，不满足 $T(\\mathbf{0}) = \\mathbf{0}$，所以不是线性变换。旋转、缩放、剪切都保持原点不动、网格平行等距。'),
  Q('一个 2×2 矩阵的**第一列**表示什么？', ['$\\hat{\\jmath}$ 变换后的位置', '$\\hat{\\imath}$ 变换后的位置', '变换后原点的位置', '矩阵的行列式'], 1, '矩阵的第 $j$ 列就是第 $j$ 个基向量变换后落到的位置。第一列对应 $\\hat{\\imath}$，第二列对应 $\\hat{\\jmath}$。'),
  Q('$\\begin{bmatrix} 1 & 2 \\\\ 3 & 4 \\end{bmatrix}\\begin{bmatrix} 1 \\\\ 1 \\end{bmatrix}$ 等于？', ['$\\begin{bmatrix} 4 \\\\ 6 \\end{bmatrix}$', '$\\begin{bmatrix} 1 \\\\ 3 \\end{bmatrix}$', '$\\begin{bmatrix} 5 \\\\ 5 \\end{bmatrix}$', '$\\begin{bmatrix} 3 \\\\ 7 \\end{bmatrix}$'], 3, '按列看：$1 \\cdot \\begin{bmatrix}1\\\\3\\end{bmatrix} + 1 \\cdot \\begin{bmatrix}2\\\\4\\end{bmatrix} = \\begin{bmatrix}3\\\\7\\end{bmatrix}$。$(4,6)$ 是每一列各自求和，相当于用全 1 的行向量去左乘，而不是右乘列向量。'),
  Q('矩阵乘积 $AB$ 作用在向量上，表示的变换顺序是？', ['先做 $B$，再做 $A$', '先做 $A$，再做 $B$', '同时做 $A$ 和 $B$', '顺序无所谓'], 0, '$(AB)\\mathbf{v} = A(B\\mathbf{v})$：$B$ 离向量最近，先作用。和函数复合 $f(g(x))$ 一样从右往左读。'),
  Q('关于矩阵乘法，下面哪个说法正确？', ['总是满足 $AB = BA$', '满足结合律 $(AB)C = A(BC)$，但一般不满足交换律', '既不满足结合律也不满足交换律', '只有方阵才能相乘'], 1, '结合律成立（都是先 $C$ 再 $B$ 再 $A$）；交换律一般不成立，比如先旋转后剪切 ≠ 先剪切后旋转。非方阵只要形状匹配也能相乘。'),
  Q('$A$ 的形状是 $(3, 4)$，$B$ 的形状是 $(4, 2)$，$AB$ 的形状是？', ['$(4, 4)$', '$(3, 4)$', '$(4, 2)$', '$(3, 2)$'], 3, '$(n, m) \\times (m, l) = (n, l)$：中间的 4 消掉，结果取两头 $(3, 2)$。'),
  Q('$A$ 的形状是 $(3, 4)$，$C$ 的形状是 $(3, 4)$，`A @ C` 会怎样？', ['得到 $(3, 3)$', '得到 $(4, 4)$', '报错，因为 $A$ 的列数 4 ≠ $C$ 的行数 3', '得到 $(3, 4)$'], 2, '矩阵乘法要求左边的列数等于右边的行数。想得到 $(3, 3)$ 应该写 `A @ C.T`（$C$ 的转置是 $(4, 3)$）。'),
  Q('一个 $2 \\times 5$ 的矩阵作为变换，把什么空间映射到什么空间？', ['五维空间 → 二维空间', '二维空间 → 五维空间', '二维空间 → 二维空间', '五维空间 → 五维空间'], 0, '它有 5 列（输入是 5 维向量），每列是 2 维向量（输出在 2 维）。$m \\times n$ 矩阵把 $n$ 维映射到 $m$ 维。'),
  Q('为什么没有激活函数的多层网络，表达能力和单层线性模型一样？', ['因为参数太少', '因为多个线性变换的复合仍然是线性变换', '因为梯度会消失', '因为矩阵乘法不满足交换律'], 1, '$W_3(W_2(W_1\\mathbf{x}))= (W_3W_2W_1)\\mathbf{x}$，可以合并成一个矩阵。非线性激活函数才让「深」有意义。'),
  Q('$(AB)_{ij}$ 的计算方法是？', ['$A_{ij} \\times B_{ij}$', '$A$ 的第 $j$ 列和 $B$ 的第 $i$ 行对应相乘再相加', '$A_{ij} + B_{ij}$', '$A$ 的第 $i$ 行和 $B$ 的第 $j$ 列对应相乘再相加'], 3, '$(AB)_{ij} = \\sum_k A_{ik}B_{kj}$。$A_{ij}\\times B_{ij}$ 是**逐元素乘积**（Hadamard 积，NumPy 里写 `A * B`），和矩阵乘法 `A @ B` 是两回事，写代码时常混淆。'),
]
